"""The migrated schema and ``models.py`` must agree, or tests and a fresh deploy would differ."""

import pytest
from alembic import command
from alembic.config import Config
from sqlalchemy import Engine, inspect, text

from paperwatch.config import ITEM_VENUE_MAX_CHARS
from paperwatch.store.models import Item

pytestmark = pytest.mark.integration


def test_models_and_migrations_do_not_drift(db_url: str) -> None:
    # `db_url` is already migrated to head; `check` autogenerates against the live schema and
    # raises `AutogenerateDiffsDetected` when `models.py` and the migrations disagree.
    # Known limit: autogenerate compares tables, columns, indexes (names, columns, uniqueness)
    # and foreign keys, but not check constraints, partial-index predicates, index storage
    # options or computed-column expressions. The `ck_items_*` constraints stay covered by the
    # repository tests, the partial HNSW index by the test below, and the `tsv` column by the
    # full-text search tests.
    cfg = Config("alembic.ini")
    cfg.set_main_option("sqlalchemy.url", db_url)
    command.check(cfg)


def test_hnsw_index_definition_matches_the_search_predicate(engine: Engine) -> None:
    # Task 10's vector query repeats ADMITTED_SQL as literal SQL, and the planner can use this
    # partial index only when the query's predicate matches the index predicate exactly, so pin
    # the operator class and the predicate here (autogenerate does not compare either).
    with engine.connect() as conn:
        indexdef = conn.scalar(
            text("SELECT indexdef FROM pg_indexes WHERE indexname = 'ix_items_embedding_hnsw'")
        )
    assert indexdef is not None
    assert "USING hnsw" in indexdef
    assert "vector_cosine_ops" in indexdef
    # Postgres normalises the varchar comparison to text, so the stored predicate is
    # `WHERE ((status)::text = 'admitted'::text)`, not the source form `status = 'admitted'`.
    assert "WHERE ((status)::text = 'admitted'::text)" in indexdef


def test_the_venue_column_holds_the_clipped_length(engine: Engine) -> None:
    # One number is the model's width, the migration's column and the clip `merge_signals` applies;
    # if any of the three drifted, a value clipped for the column could still fail the write.
    assert Item.venue.type.length == ITEM_VENUE_MAX_CHARS
    columns = {column["name"]: column for column in inspect(engine).get_columns("items")}
    assert columns["venue"]["type"].length == ITEM_VENUE_MAX_CHARS
